import {chapters,words,practice,writing} from './content.js';
import {createWorld} from './scene.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='last-straw-lesson6-v1';
const fresh=()=>({version:1,started:false,current:0,pages:[0,0,0,0],done:[false,false,false,false],solved:{},attempts:[],practice:{},pledge:'',motion:!matchMedia('(prefers-reduced-motion: reduce)').matches});
let state=fresh(),storageAvailable=true;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s?.version===1&&Array.isArray(s.done)&&s.done.length===4&&Array.isArray(s.pages)&&s.pages.length===4&&typeof s.current==='number'&&s.current>=0&&s.current<4&&s.solved&&Array.isArray(s.attempts)&&s.practice){state={...fresh(),...s};state.pages=state.pages.map((p,i)=>Number.isInteger(p)?Math.max(0,Math.min(p,chapters[i].pages.length-1)):0);}}catch{storageAvailable=false;}
let playing=false,world=null,ready=false,worldFailed=false,tab='notes',page=0,toastTimer,finishing=false;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='進度已儲存 · 此瀏覽器';}catch{storageAvailable=false;$('#save-status').textContent='此瀏覽器無法保存進度';}}
function unlocked(i){return i===0||state.done.slice(0,i).every(Boolean);}
function update(){
 const ch=chapters[state.current];$('#chapter-label').textContent=`CHAPTER 0${state.current+1} / ${ch.en}`;$('#mission-title').textContent=ch.title;$('#mission-description').textContent=state.done[state.current]?'這一章已完成。你可以再次閱讀，或前往下一個已解鎖章節。':ch.description;
 $('#location-tag').innerHTML=`0${state.current+1} / ${ch.en}<span>${escape(ch.place)}</span>`;
 $$('.chapters button').forEach((b,i)=>{b.classList.toggle('active',i===state.current);b.classList.toggle('done',state.done[i]);b.setAttribute('aria-current',i===state.current?'step':'false');b.setAttribute('aria-label',`${i+1} ${chapters[i].short}${!unlocked(i)?'，尚未解鎖':state.done[i]?'，已完成':''}`);b.style.opacity=unlocked(i)?'1':'.5';});
 $('#motion-btn').textContent=`動態效果：${state.motion?'開':'關'}`;$('#start-btn').innerHTML=`${state.started?'繼續海岸故事':'走進故事'} <span>↗</span>`;$('#restart-btn').hidden=!state.started;
}
function syncDialog(){const open=$$('dialog').some(d=>d.open);world?.setDialog(open);$('#crosshair').hidden=!playing||open;}
function openDialog(id){$$('dialog').forEach(d=>{if(d.open)d.close();});const dialog=$(id);dialog.showModal();syncDialog();}
function closeDialog(id){$(id).close();syncDialog();}
$$('dialog').forEach(d=>{d.addEventListener('close',syncDialog);d.addEventListener('cancel',()=>setTimeout(syncDialog,0));});
function start(){
 if(!ready&&!worldFailed){toast('正在準備海岸，請稍候。');return;}
 playing=true;state.started=true;save();document.body.classList.add('playing');$('#welcome').hidden=true;$('#mission').hidden=false;$('#read-btn').disabled=!worldFailed;$('#crosshair').hidden=worldFailed;$('#look-btn').hidden=worldFailed;$('#move-controls').hidden=worldFailed||!matchMedia('(pointer:coarse)').matches;
 world?.start(state.current);update();if(!storageAvailable)toast('目前無法儲存進度，但仍可繼續閱讀。');else toast('沿著木棧道前進，或點「帶我前往」。');
 if(worldFailed){$('#read-btn').disabled=false;$('#guide-btn').disabled=true;toast('3D 無法啟用；仍可使用「閱讀現場」完成所有章節。');}
}
function setChapter(i){if(!playing){toast('先點「走進故事」，開始 Ann 的旅程。');return;}if(!unlocked(i)){toast('先讀完前一章，故事才會往下走。');return;}state.current=i;page=state.pages[i];finishing=false;world?.setChapter(i);save();update();$('#read-btn').disabled=!worldFailed;toast(`接下來：${chapters[i].place}。可使用「帶我前往」。`);}
function read(){if(!playing)return;if(!worldFailed&&!world?.isNear()){toast('先走近橘色章節標記，或點「帶我前往」。');return;}page=state.pages[state.current];finishing=false;renderPage();openDialog('#reader');}
const answerKey=()=>`${state.current}-${page}`;
function renderPage(){
 finishing=false;const ch=chapters[state.current],p=ch.pages[page],key=answerKey(),selected=state.solved[key],solved=Number.isInteger(selected);
 $('#reader-kicker').textContent=`0${state.current+1} / ${ch.en}`;
 $('#reader-content').innerHTML=`<span class="source-label">${escape(p.source)}</span><h2 id="reader-title">${escape(p.title)}</h2>${p.narration?`<p class="narration">${escape(p.narration)}</p>`:''}<div class="english" lang="en">${escape(p.english)}</div><details class="translation"><summary>需要時，看看中文提示</summary><p>${escape(p.zh)}</p></details>${p.words?`<div class="word-strip">${escape(p.words)}</div>`:''}${p.question?`<div class="question">${escape(p.question)}</div><div class="options">${p.options.map((o,i)=>`<button data-answer="${i}" ${solved?'disabled':''} class="${solved&&(p.answer===null?selected===i:p.answer===i)?'correct':''}"><span>${String.fromCharCode(65+i)}.</span> ${escape(o)}</button>`).join('')}</div><div id="answer-feedback" role="status" aria-live="polite">${solved?`<div class="feedback">${p.answer===null?'承諾已記下。':'理解正確。'}${escape(p.explanation)}</div>`:''}</div>`:''}`;
 $('#page-indicator').textContent=`${page+1} / ${ch.pages.length} 段`;$('.reader-footer').hidden=false;$('#previous-page').hidden=page===0;$('#next-page').disabled=!!p.question&&!solved;$('#next-page').textContent=page===ch.pages.length-1?(state.done[state.current]?'本章回顧 ✓':'完成本章 →'):'繼續閱讀 →';
 $('#reader').scrollTop=0;
 $$('[data-answer]').forEach(b=>b.addEventListener('click',()=>answer(Number(b.dataset.answer))));
}
function answer(index){const p=chapters[state.current].pages[page],key=answerKey(),correct=p.answer===null||index===p.answer;if(Number.isInteger(state.solved[key]))return;
 state.attempts.push({id:key,kind:'story',question:p.question,chosen:p.options[index],correct,expected:p.answer===null?p.options[index]:p.options[p.answer],explanation:p.explanation});
 if(correct){state.solved[key]=index;if(p.answer===null)state.pledge=p.options[index];save();renderPage();}
 else{$$('[data-answer]').forEach(b=>b.classList.toggle('wrong',Number(b.dataset.answer)===index));$('#answer-feedback').innerHTML=`<div class="feedback retry">再回到上面的英文找找線索。${escape(p.explanation)}<br>想一想，再選一次。</div>`;save();}
}
function finishChapter(){state.done[state.current]=true;save();update();finishing=true;const all=state.done.every(Boolean),i=state.current;
 $('#reader-content').innerHTML=`<span class="source-label">CHAPTER 0${i+1} COMPLETE</span><h2 id="reader-title">${all?'信，已放進海岸信箱。':'把這一段，留在手帳裡。'}</h2><div class="completion">${all?'你已經走過四章故事。從吸管、塑膠袋到餐廳的餐具，你用英文理解問題，也為自己的建議找到了理由。':'你完成了這一章的閱讀與任務。下一站的故事已經解鎖。'}</div><div class="note-card"><h3>我讀懂了</h3><p>${escape(chapters[i].note)}</p></div>${all?`<div class="note-card"><h3>我的承諾</h3><p class="english">${escape(state.pledge)}</p><p>故事中的寄信是遊戲情節，沒有對外傳送訊息。</p></div><p class="source-note">本遊戲新增的結尾不代表餐廳已承諾改變。你可以在手帳練習教材題目，或再次探索海岸。</p><button id="export-report" class="primary">下載學習紀錄 ↓</button> <button id="finish-notes">打開閱讀手帳</button>`:`<p class="narration">${escape(chapters[i+1].description)}</p><button id="continue-chapter" class="primary">前往下一章 →</button>`}`;
 $('.reader-footer').hidden=true;$('#reader').scrollTop=0;
 $('#continue-chapter')?.addEventListener('click',()=>{closeDialog('#reader');setChapter(i+1);world?.guide();});
 $('#finish-notes')?.addEventListener('click',()=>openNotebook('notes'));$('#export-report')?.addEventListener('click',exportReport);
}
$('#next-page').addEventListener('click',()=>{const p=chapters[state.current].pages[page];if(p.question&&!Number.isInteger(state.solved[answerKey()]))return;if(page===chapters[state.current].pages.length-1){finishChapter();return;}page++;state.pages[state.current]=page;save();renderPage();});
$('#previous-page').addEventListener('click',()=>{if(page>0){page--;state.pages[state.current]=page;save();renderPage();}});
function openNotebook(t=tab){tab=t;renderNotebook();openDialog('#notebook');}
function renderNotebook(){
 $$('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));
 const el=$('#notebook-content');
 if(tab==='notes'){el.innerHTML=`<p class="source-note">${state.done.filter(Boolean).length} / 4 章完成 · ${Object.keys(state.solved).length} / ${chapters.reduce((n,ch)=>n+ch.pages.filter(p=>p.question).length,0)} 個故事任務完成</p>${chapters.map((ch,i)=>`<div class="note-card"><h3>0${i+1} ${escape(ch.title)} <span class="badge">${state.done[i]?'✓ 已完成':unlocked(i)?'待探索':'尚未解鎖'}</span></h3><p>${state.done[i]?escape(ch.note):'讀完章節後，在這裡留下知識筆記。'}</p>${state.done[i]?`<button data-revisit="${i}">回到這一章</button>`:''}</div>`).join('')}${state.pledge?`<div class="note-card"><h3>我的承諾</h3><p class="english">${escape(state.pledge)}</p></div>`:''}<div class="note-card"><h3>三個文法提醒</h3><p>One / Each of + 複數名詞 → 單數動詞。<br>Both / Many of + 複數名詞 → 複數動詞。<br>Some / Most / All of → 依所指名詞決定單複數。</p><p>If + 現在式，主句可用 will / can / may / might + 原形動詞，或祈使句。</p><p>Although / Though + 子句表轉折；這個句型不再加 but。</p></div><button id="download-notes">下載學習紀錄 ↓</button><p class="source-note">教材來源：159148_0.jpg 至 159155_0.jpg。對話 p.230–231、閱讀 p.235、文法 p.239–242、字彙表。遊戲新增情節與改編題已個別標示。2050 年的預測未作為遊戲結論或計分知識。</p>`;
  $$('[data-revisit]').forEach(b=>b.addEventListener('click',()=>{if(!playing)start();closeDialog('#notebook');setChapter(Number(b.dataset.revisit));state.pages[state.current]=0;save();world?.guide();}));$('#download-notes').onclick=exportReport;
 }else if(tab==='words'){el.innerHTML=`<p class="source-note">教材字彙表 · 40 個字詞，部分包含過去式或複數。</p><div class="word-grid">${words.map(([en,zh])=>`<div class="word-entry"><strong lang="en">${escape(en)}</strong><span>${escape(zh)}</span></div>`).join('')}</div>`;
 }else if(tab==='practice'){el.innerHTML=`<p class="source-note">教材原題重現；答案與解析由本遊戲依文法推導，非另附的教師答案。練習不影響故事解鎖。已完成 ${Object.keys(state.practice).length} / 20 題。</p><h3>選擇題 · 10 題</h3>${practice.map(p=>`<section class="practice-card" data-practice="${p.id}"><span class="source-label">${p.source}</span><h3 lang="en">${escape(p.q)}</h3><div class="options">${p.options.map((o,j)=>`<button data-practice-answer="${p.id}" data-option="${j}" class="${state.practice[p.id]&&j===p.answer?'correct':''}" ${state.practice[p.id]?'disabled':''}>${String.fromCharCode(65+j)}. ${escape(o)}</button>`).join('')}</div><div class="practice-feedback" role="status">${state.practice[p.id]?`<div class="feedback">${escape(p.explanation)}</div>`:''}</div></section>`).join('')}<h3>改寫與重組 · 10 題</h3><p class="source-note">輸入完整句子。重組題也能點選詞塊；自動比對只辨識參考寫法，其他合理答案可展開解析自評。</p>${writing.map(p=>`<section class="practice-card" data-writing="${p.id}"><span class="source-label">${p.source}</span><h3>${escape(p.q)}</h3>${p.q.includes(' / ')?`<div class="word-chips">${p.q.split(' / ').map((s,j)=>({s,j})).reverse().map(({s,j})=>`<button data-word="${escape(s)}" data-writing-id="${p.id}" data-chip="${j}">${escape(s)}</button>`).join('')}</div>`:''}<input class="practice-answer" aria-label="${p.source} 的答案" id="input-${p.id}" placeholder="在這裡寫下你的句子…" autocomplete="off" spellcheck="false"><button data-check="${p.id}">比對參考句</button> <button data-clear="${p.id}">清空</button><div class="writing-feedback" role="status">${state.practice[p.id]?'<p class="badge">✓ 已完成</p>':''}</div><details class="translation"><summary>查看參考答案與解析</summary><p lang="en">${escape(p.answer)}</p><p>${escape(p.explanation)}</p><button data-selfcheck="${p.id}">我已核對並理解</button></details></section>`).join('')}`;
  $$('[data-practice-answer]').forEach(b=>b.onclick=()=>practiceAnswer(b));
  $$('[data-word]').forEach(b=>b.onclick=()=>{const input=$(`#input-${b.dataset.writingId}`);input.value=(input.value+' '+b.dataset.word).trim();b.disabled=true;});
  $$('[data-clear]').forEach(b=>b.onclick=()=>{$(`#input-${b.dataset.clear}`).value='';$$(`[data-writing-id="${b.dataset.clear}"]`).forEach(c=>c.disabled=false);});
  $$('[data-check]').forEach(b=>b.onclick=()=>checkWriting(b.dataset.check));
  $$('[data-selfcheck]').forEach(b=>b.onclick=()=>{state.practice[b.dataset.selfcheck]=true;save();b.textContent='✓ 已理解';b.disabled=true;});
 }else{const wrong=state.attempts.filter(a=>!a.correct);const unique=[...new Map(wrong.map(a=>[a.id,a])).values()];el.innerHTML=unique.length?`<p class="source-note">共 ${unique.length} 題曾需要再想一次。錯誤是閱讀的一部分；以下保留線索供你回顧。</p>${unique.map(a=>`<div class="note-card"><h3>${escape(a.question)}</h3><p>我曾選擇：${escape(a.chosen)}</p><p>參考答案：${escape(a.expected)}</p><p>${escape(a.explanation)}</p><span class="badge">${(a.kind==='story'?Number.isInteger(state.solved[a.id]):state.practice[a.id])?'已理解':'待複習'}</span></div>`).join('')}`:'<div class="note-card"><h3>這裡還沒有錯題。</h3><p>遇到需要再想一次的題目，手帳會保存原題與解析。</p></div>';}
}
function practiceAnswer(b){const p=practice.find(p=>p.id===b.dataset.practiceAnswer),i=Number(b.dataset.option),correct=i===p.answer,card=b.closest('.practice-card');state.attempts.push({id:p.id,kind:'practice',question:p.q,chosen:p.options[i],expected:p.options[p.answer],correct,explanation:p.explanation});if(correct){state.practice[p.id]=true;card.querySelectorAll('button').forEach(x=>x.disabled=true);b.classList.add('correct');}else{card.querySelectorAll('button').forEach(x=>x.classList.remove('wrong'));b.classList.add('wrong');}card.querySelector('.practice-feedback').innerHTML=`<div class="feedback ${correct?'':'retry'}">${correct?'正確。':'再想一下。'}${escape(p.explanation)}</div>`;save();}
const normalize=s=>s.toLowerCase().replace(/[’‘]/g,"'").replace(/you'll/g,'you will').replace(/don't/g,'do not').replace(/isn't/g,'is not').replace(/[.,;!?]/g,' ').replace(/\s+/g,' ').trim();
function checkWriting(id){const p=writing.find(x=>x.id===id),input=$(`#input-${id}`),value=input.value.trim(),card=input.closest('.practice-card');if(!value){toast('先試著寫一句，再比對參考答案。');return;}const matches=[p.answer,...(p.alternatives||[])].some(a=>normalize(a)===normalize(value));if(matches)state.practice[id]=true;card.querySelector('.writing-feedback').innerHTML=`<div class="feedback ${matches?'':'retry'}">${matches?'✓ 與參考寫法相符。':'這個寫法未與內建參考句相符；不代表一定錯誤。展開解析，比較主詞、動詞與句意，也可以請老師協助核對。'}${matches?escape(p.explanation):''}</div>`;save();}
function exportReport(){const mistakes=[...new Map(state.attempts.filter(a=>!a.correct).map(a=>[a.id,a])).values()];const report=`最後一根吸管 — Lesson 6 學習紀錄\n\n章節完成：${state.done.filter(Boolean).length}/4\n故事任務完成：${Object.keys(state.solved).length}/${chapters.reduce((n,ch)=>n+ch.pages.filter(p=>p.question).length,0)}\n教材練習完成：${Object.keys(state.practice).length}/20\n\n我的承諾：${state.pledge||'尚未選擇'}\n\n${chapters.map((ch,i)=>`${state.done[i]?'✓':'○'} ${ch.title}\n${state.done[i]?ch.note:'尚未完成'}`).join('\n\n')}\n\n錯題回顧\n${mistakes.map(a=>`${a.question}\n曾選：${a.chosen}\n參考：${a.expected}\n${a.explanation}`).join('\n\n')||'目前沒有錯題。'}\n\n資料來源：使用者提供之 Lesson 6 教材照片。故事寄信為遊戲情節。\n`;const url=URL.createObjectURL(new Blob(['\uFEFF'+report],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='The-Last-Straw-Learning-Notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('學習紀錄已準備下載。');}
function restartGame(){if(!confirm('要清除這個瀏覽器的遊戲進度與練習紀錄，重新開始嗎？'))return;state=fresh();save();location.reload();}
const resetButton=document.createElement('button');resetButton.id='reset-progress';resetButton.className='text-button';resetButton.textContent='重新開始故事';resetButton.onclick=restartGame;$('#help').appendChild(resetButton);
$('#start-btn').onclick=start;$('#restart-btn').onclick=restartGame;
$('#guide-btn').onclick=()=>world?.guide();$('#read-btn').onclick=read;$('#interaction').onclick=read;$('#look-btn').onclick=()=>{world?.lock();toast('移動滑鼠環顧；Esc 釋放滑鼠。也可以拖曳場景觀看。');};
$('#journal-btn').onclick=()=>openNotebook();$('#close-reader').onclick=()=>closeDialog('#reader');$('#close-notebook').onclick=()=>closeDialog('#notebook');$('#help-btn').onclick=()=>openDialog('#help');$('#close-help').onclick=()=>closeDialog('#help');$('#help-done').onclick=()=>closeDialog('#help');
$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderNotebook();});$$('[data-chapter]').forEach(b=>b.onclick=()=>setChapter(Number(b.dataset.chapter)));
$('#motion-btn').onclick=()=>{state.motion=!state.motion;world?.setMotion(state.motion);save();update();};
$$('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);world?.move(b.dataset.move,true);});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>world?.move(b.dataset.move,false));});
addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.repeat)return;const hasDialog=$$('dialog').some(d=>d.open);if(e.code==='KeyJ'){e.preventDefault();if($('#notebook').open)closeDialog('#notebook');else openNotebook();}else if(e.code==='KeyE'&&playing&&!hasDialog)read();});
try{world=createWorld($('#world'),{onNear(near){$('#interaction').hidden=!near||!playing;$('#interaction').textContent=`E · 閱讀${chapters[state.current].place}`;$('#read-btn').disabled=!near;},onReady(){ready=true;},onError(error){worldFailed=true;ready=true;$('#save-status').textContent='3D 顯示受限 · 可繼續閱讀';if(playing){$('#read-btn').disabled=false;$('#guide-btn').disabled=true;}toast(error.message||'3D 無法啟用，仍可使用閱讀模式。');}});world?.setMotion(state.motion);}catch(error){worldFailed=true;ready=true;toast('3D 顯示受限。點「走進故事」後，可使用閱讀模式。');console.error(error);}
update();if(state.started)$('#save-status').textContent='已找到上次的閱讀進度';

